<?php
require '../config/app.php';require_role('admin');$title='Manage Tests';$basePath='../';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action'];if($action==='delete'){$st=$pdo->prepare("DELETE FROM diagnostic_tests WHERE id=?");try{$st->execute([(int)$_POST['id']]);flash('success','Test deleted.');}catch(PDOException $e){flash('danger','Test cannot be deleted because it is used by an appointment.');}}
else{$id=(int)($_POST['id']??0);$name=trim($_POST['name']);$cat=trim($_POST['category']);$desc=trim($_POST['description']);$price=(float)$_POST['price'];$dur=(int)$_POST['duration'];if($id){$st=$pdo->prepare("UPDATE diagnostic_tests SET name=?,category=?,description=?,price=?,duration_minutes=? WHERE id=?");$st->execute([$name,$cat,$desc,$price,$dur,$id]);}else{$st=$pdo->prepare("INSERT INTO diagnostic_tests(name,category,description,price,duration_minutes) VALUES(?,?,?,?,?)");$st->execute([$name,$cat,$desc,$price,$dur]);}flash('success','Test saved.');}redirect('tests.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM diagnostic_tests WHERE id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$tests=$pdo->query("SELECT * FROM diagnostic_tests ORDER BY category,name")->fetchAll();require '../partials/header.php';?>
<div class="row g-4"><div class="col-lg-5"><div class="card p-4"><h4><?= $edit?'Edit':'Add' ?> Diagnostic Test</h4><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>">
<label class="form-label">Name</label><input class="form-control mb-2" name="name" required value="<?=e($edit['name']??'')?>"><label class="form-label">Category</label><input class="form-control mb-2" name="category" required value="<?=e($edit['category']??'')?>"><label class="form-label">Description</label><textarea class="form-control mb-2" name="description"><?=e($edit['description']??'')?></textarea><label class="form-label">Price</label><input class="form-control mb-2" type="number" step="0.01" name="price" required value="<?=e($edit['price']??'')?>"><label class="form-label">Duration (minutes)</label><input class="form-control mb-3" type="number" name="duration" required value="<?=e($edit['duration_minutes']??30)?>"><button class="btn btn-primary">Save Test</button> <?php if($edit):?><a class="btn btn-light" href="tests.php">Cancel</a><?php endif;?></form></div></div>
<div class="col-lg-7"><div class="card p-3"><h5>Diagnostic Tests</h5><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Category</th><th>Price</th><th></th></tr></thead><tbody><?php foreach($tests as $t):?><tr><td><?=e($t['name'])?></td><td><?=e($t['category'])?></td><td><?=money($t['price'])?></td><td><a href="?edit=<?=$t['id']?>" class="btn btn-sm btn-outline-primary">Edit</a><form class="d-inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$t['id']?>"><button data-confirm="Delete this test?" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require '../partials/footer.php'; ?>
